import json
import requests
import chardet

API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content)
        if detected['confidence'] > 0.5:
            from_encoding = detected['encoding']
        else:
            raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded = content.decode(from_encoding)
        re_encoded = decoded.encode(to_encoding)
        return json.loads(re_encoded)
    except (UnicodeDecodeError, UnicodeEncodeError, json.JSONDecodeError):
        raise ValueError("Unable to process content with given encodings")

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error: {e}")

    tree = html.fromstring(response.content)
    table_elements = tree.xpath('//table')
    if not table_elements:
        return 0

    table = table_elements[0]
    headers = []
    header_elements = table.xpath('.//th')
    for header in header_elements:
        headers.append(header.text_content().strip())

    rows = []
    for row in table.xpath('.//tr'):
        cols = row.xpath('.//td')
        if cols:
            row_data = [col.text_content().strip() for col in cols]
            rows.append(row_data)

    if not rows:
        return 0

    df = pd.DataFrame(rows, columns=headers if headers else None)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(rows)

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise ValueError("Repository URL must be provided.")

    try:
        response = requests.get(repo_url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if response.status_code == 403 and 'rate limit' in response.text.lower():
            raise requests.exceptions.HTTPError(f"GitHub API rate limit exceeded: {e}")
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

    repo_info = response.json()
    open_issues_count = repo_info.get('open_issues_count', 0)
    if open_issues_count > 1000:
        logging.warning(f"Repository has a large number of open issues: {open_issues_count}")

    return repo_info

