import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = value
    return normalized_data

import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("Invalid URL or parameters.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("No data received from the API.")
        df = pd.DataFrame(data)
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical data to compute correlations.")
        corr_matrix = numeric_df.corr()
        fig, ax = plt.subplots()
        sns.heatmap(corr_matrix, annot=True, ax=ax)
        return (df, ax)
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    except (ValueError, json.JSONDecodeError) as e:
        raise Exception(f"Invalid data received: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")
